function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function listOrEmpty(value){return Array.isArray(value)?value:[]}
function options(items,selected=''){return '<option value="">不使用</option>'+listOrEmpty(items).map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}
function promptField(section='manual'){return $(PROMPT_SECTION_IDS[section]||PROMPT_SECTION_IDS.manual)}
function normalizedClientTerm(value){return String(value||'').trim().toLowerCase().replace(/\\([()])/g,'$1').replace(/_/g,' ').replace(/\s+/g,' ').replace(/^\((.*):\s*[0-2](?:\.\d+)?\)$/,'$1').replace(/[ .]+$/,'')}
function splitClientTerms(value){return String(value||'').split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean)}
function appendEnglish(en,section='manual'){const field=promptField(section),incoming=splitClientTerms(en),existing=splitClientTerms(field.value),known=new Set(existing.map(normalizedClientTerm)),added=[];incoming.forEach(term=>{const key=normalizedClientTerm(term);if(key&&!known.has(key)){known.add(key);existing.push(term);added.push(term)}});if(!added.length)return false;field.value=existing.join(', ');tokenHistory.push({field:field.id,terms:added});promptEditorChanged();field.focus();return true}
function prependEnglish(en){return appendEnglish(en,'manual')}
function renderTokens(){const root=$('tokenGroups');root.innerHTML='';Object.entries(tokenLibrary).forEach(([group,items])=>{const box=document.createElement('div');box.className='token-group';box.innerHTML=`<div class="group-name">${group}</div><div class="tokens"></div>`;const list=box.querySelector('.tokens');items.forEach(([zh,en,section='manual'])=>{const b=document.createElement('button');b.className='token';b.type='button';b.textContent=zh;b.title=en;b.onclick=()=>appendToken(en,zh,b,section);list.appendChild(b)});if(cascadeLibrary[group])renderCascades(box,cascadeLibrary[group],group);root.appendChild(box)})}
function renderCascades(box,menus,group){const root=document.createElement('div');root.className='cascades';const section=group==='头发与眼睛'?'appearance':'clothing';menus.forEach(menu=>{const wrap=document.createElement('div');wrap.className='cascade';const title=document.createElement('div');title.className='cascade-title';title.textContent=menu.title;const row=document.createElement('div');row.className='cascade-row';const type=document.createElement('select'),color=document.createElement('select'),add=document.createElement('button');type.innerHTML=menu.types.map(([zh,en])=>`<option value="${esc(en)}">${esc(zh)}</option>`).join('');color.innerHTML=menu.colors.map(([zh,en])=>`<option value="${esc(en)}">${esc(zh)}</option>`).join('');add.type='button';add.textContent='确认加入';add.onclick=()=>{const tag=menu.compose(type.value,color.value);if(!tag)return;const added=appendEnglish(tag,section);$('tokenHint').textContent=added?'已添加到'+(section==='appearance'?'外貌':'服装与材质')+'：'+type.options[type.selectedIndex].text+' · '+color.options[color.selectedIndex].text:'对应分区中已有该组合'};row.append(type,color,add);wrap.append(title,row);root.appendChild(wrap)});box.appendChild(root)}
function appendToken(en,zh,button,section='manual'){const added=appendEnglish(en,section);if(added){button.classList.add('active');$('tokenHint').textContent=`已添加到${sectionLabel(section)}：${zh}`}else $('tokenHint').textContent='对应分区中已有：'+zh}
function sectionLabel(section){return{subject:'人物与角色',appearance:'外貌',clothing:'服装与材质',pose:'姿势',composition:'构图',scene:'场景',lighting:'光线',style:'画风与上色',naturalLanguage:'自然语言',manual:'其他补充'}[section]||'其他补充'}
function inferSectionForEnglish(text){const value=normalizedClientTerm(text);if(/\b(1girl|2girls|1boy|2boys|woman|man|character)\b/.test(value))return'subject';if(/\b(hair|eyes|skin|blush|freckles|heterochromia)\b/.test(value))return'appearance';if(/\b(shirt|dress|skirt|pants|shorts|uniform|coat|jacket|gloves|shoes|heels|pantyhose|tights|stockings|thighhighs|socks|fabric|nylon)\b/.test(value))return'clothing';if(/\b(standing|sitting|lying|smile|looking|holding|crossed legs|pose)\b/.test(value))return'pose';if(/\b(full body|upper body|portrait|close-up|view|angle|perspective|depth of field)\b/.test(value))return'composition';if(/\b(indoors|outdoors|background|classroom|corridor|city|seaside|cherry blossoms)\b/.test(value))return'scene';if(/\b(light|lighting|shadow|sunlight|daylight|rim light|neon)\b/.test(value))return'lighting';if(/\b(masterpiece|quality|highres|anime|lineart|painting|illustration|style)\b/.test(value))return'style';return'manual'}
function convertChinese(){const source=$('zhPrompt').value.trim();if(!source){$('translationResult').textContent='请先输入中文描述。';return}const occupied=[],hits=[];Object.keys(chineseMap).sort((a,b)=>b.length-a.length).forEach(zh=>{const start=source.indexOf(zh);if(start<0)return;const end=start+zh.length;if(occupied.some(range=>start<range.end&&end>range.start))return;occupied.push({start,end});hits.push({zh,en:chineseMap[zh]})});let added=0;hits.forEach(item=>{if(appendEnglish(item.en,inferSectionForEnglish(item.en)))added++});const recognized=hits.map(x=>x.zh).join('、');$('translationResult').textContent=hits.length?`识别 ${hits.length} 个互不重叠的常用词，新增 ${added} 组：${recognized}`:'未识别到常用词；可改用通用 AI 结构化转换或标签搜索。'}
