function updateAIProviderInfo(){const provider=$('aiProvider').value,preset=AI_PROVIDER_PRESETS[provider],protocol=$('aiProtocol').value,auth=$('aiAuthType').value;const names={openai:'OpenAI 兼容',anthropic:'Anthropic Messages',gemini:'Gemini generateContent'},authNames={bearer:'Bearer', 'x-api-key':'x-api-key','api-key':'api-key','x-goog-api-key':'x-goog-api-key',none:'无需密钥'};$('aiProviderInfo').textContent=`${preset?.label||'自定义服务'} · ${names[protocol]} · ${authNames[auth]}`}
