async function translateAI(){const text=$('zhPrompt').value.trim(),key=$('aiKey').value.trim(),protocol=$('aiProtocol').value,authType=$('aiAuthType').value,endpoint=$('aiEndpoint').value.trim(),model=$('aiModel').value.trim(),provider=$('aiProvider').value,checkpoint=$('model').value||'',safetyLevel=$('safetyLevel').value||'safe';if(!text){$('translationResult').textContent='请先输入中文描述。';return}if(!endpoint){$('translationResult').textContent='请填写完整的 API 请求地址。';return}if(!key&&authType!=='none'){$('translationResult').textContent='请填写 API Key，或将鉴权方式改为“无需密钥”。';return}if((protocol==='anthropic'||protocol==='gemini')&&!model){$('translationResult').textContent='当前协议必须填写模型名称。';return}$('translationResult').textContent=`${AI_PROVIDER_PRESETS[provider]?.label||'自定义 AI'} 正在按【${translationFamilyLabel(promptFamilyClient())}】转换…`;$('translationPreview').style.display='none';try{const r=await fetch('/api/translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,apiKey:key,protocol,authType,endpoint,model,family:promptFamilyClient(),checkpoint,safetyLevel})}),data=await r.json();if(data.error)throw Error(data.error);translated={positive:data.positive||'',negative:data.negative||'',family:data.family||promptFamilyClient(),promptMode:data.promptMode||'flat',sections:data.sections||{}};$('translatedPositive').textContent=translated.positive||'（未返回正向提示词）';$('translatedNegative').textContent=translated.negative||'（基础负面词由本地编译器生成）';$('translationPreview').style.display='block';$('translationResult').textContent=`转换完成：已按【${translationFamilyLabel(translated.family)}】生成完整正向提示词。`}catch(e){$('translationResult').textContent='转换失败：'+e.message}}
