let tagTimer;async function searchTags(){clearTimeout(tagTimer);const input=$('tagSearch').value.trim();const root=$('tagResults');if(!input){root.innerHTML='<span class="small">输入内容后显示候选；点击即可插入规范英文标签。</span>';return}tagTimer=setTimeout(async()=>{try{const data=await(await fetch('/api/tags?q='+encodeURIComponent(input))).json();root.innerHTML=data.tags.length?'':'<span class="small">没有找到匹配标签。</span>';data.tags.forEach(item=>{const b=document.createElement('button');b.className='token';b.type='button';b.innerHTML=`${esc(item.tag)} <small>${esc(item.translation||item.category)} · ${item.count.toLocaleString()}</small>`;b.title=`${item.category}${item.translation?'：'+item.translation:''}`;b.onclick=()=>{const section=$('tagTarget').value;appendEnglish(item.tag,section);$('tagSearch').value='';root.innerHTML='<span class="small">已插入到'+sectionLabel(section)+'：'+esc(item.tag)+'</span>'};root.appendChild(b)});}catch(e){root.innerHTML='<span class="small">标签库读取失败：'+esc(e.message)+'</span>'}},180)}
function updateCount(){const ids=[...new Set(Object.values(PROMPT_SECTION_IDS))],total=ids.reduce((sum,id)=>sum+splitClientTerms($(id)?.value).length,0);$('promptCount').textContent=total+' 个内容标签'}
function noteKey(name){return String(name||'').replace(/\\/g,'/').replace(/^\.\//,'')}
function noteBaseKey(name){return noteKey(name).split('/').pop()}
function noteLookupKey(name){const full=noteKey(name),base=noteBaseKey(name);return Object.prototype.hasOwnProperty.call(loraNotes,full)?full:base}
function loraNoteForName(name){return loraNotes[noteKey(name)]||loraNotes[noteBaseKey(name)]||{}}
function sidecarKey(name){return String(name||'').replace(/\\/g,'/').replace(/\.safetensors$/i,'')}
function selectedSidecar(){return loraSidecars[sidecarKey(currentLoraName)]||null}
function loraFolderOptions(){const folders=new Set();Object.values(catalog.loraMeta||{}).forEach(m=>{if(m&&m.folder)folders.add(m.folder)});return '<option value="">全部文件夹</option>'+[...folders].sort().map(f=>`<option value="${esc(f)}">${esc(f)}</option>`).join('')}
function loraFamilyVisible(family){const cur=promptFamilyClient();if(cur==='anima')return family==='anima'||family==='general';if(cur==='krea2')return family==='krea2'||family==='general';return family!=='anima'&&family!=='krea2'}
function filteredLoras(){const folder=$('loraFolder').value,meta=catalog.loraMeta||{};return listOrEmpty(catalog.loras).filter(name=>{const m=meta[name]||{};if(folder&&m.folder!==folder)return false;return loraFamilyVisible(m.family)})}
function refreshLoraSelects(){const list=filteredLoras();document.querySelectorAll('#loras select').forEach(sel=>{const cur=sel.value;sel.innerHTML=options(list,cur);if(cur&&!list.includes(cur)){const o=document.createElement('option');o.value=cur;o.textContent=cur;o.selected=true;sel.appendChild(o)}});const info=$('loraFilterInfo');if(info)info.textContent=`当前 ${list.length} 个 LoRA`}
function saveLoraState(){try{const items=selectedLoraPayload();if(items.length)sessionStorage.setItem(LORA_STATE_STORAGE,JSON.stringify(items));else sessionStorage.removeItem(LORA_STATE_STORAGE)}catch{}}
function restoreLoraState(){let saved=[];try{const value=JSON.parse(sessionStorage.getItem(LORA_STATE_STORAGE)||'[]');if(Array.isArray(value))saved=value}catch{}const valid=saved.filter(item=>item&&catalog.loras.includes(item.name)).slice(0,16),validKeys=new Set(valid.map(item=>noteKey(item.name))),orphaned=appliedOutfits.filter(p=>!validKeys.has(p.key));orphaned.forEach(p=>removeOutfitSections(p.item,p.state));if(orphaned.length)setAppliedOutfits(appliedOutfits.filter(p=>validKeys.has(p.key)));$('loras').innerHTML='';if(valid.length)valid.forEach(item=>addLora(item.name,String(item.weight??'0.70')));else addLora();saveLoraState()}
function removeAppliedOutfitsForLora(name){const key=noteKey(name);if(!key)return 0;const removed=appliedOutfits.filter(p=>p.key===key),remaining=appliedOutfits.filter(p=>p.key!==key);removed.forEach(p=>removeOutfitSections(p.item,p.state));if(removed.length)setAppliedOutfits(remaining);return removed.length}
function addLora(name='',weight='0.70'){const row=document.createElement('div');row.className='row';const select=document.createElement('select');let loraList=filteredLoras();if(name&&!loraList.includes(name))loraList=[name,...loraList];select.innerHTML=options(loraList,name);select.dataset.loraName=name;const activateMemo=()=>{const previous=select.dataset.loraName||'';if(previous!==select.value){removeAppliedOutfitsForLora(previous);select.dataset.loraName=select.value;saveLoraState()}selectLoraNote(select.value);renderRegions();promptEditorChanged()};select.onchange=activateMemo;select.oninput=activateMemo;select.onfocus=()=>selectLoraNote(select.value);select.onmousedown=()=>selectLoraNote(select.value);const strength=document.createElement('input');strength.type='number';strength.min='0';strength.max='1.5';strength.step='0.05';strength.value=weight;strength.title='LoRA 权重：0.7–1.0 常规；越高角色特征越强，过高易过拟合/崩坏。';strength.oninput=()=>{saveLoraState();promptEditorChanged()};const remove=document.createElement('button');remove.title='移除';remove.textContent='×';remove.onclick=()=>{const wasActive=select.value===currentLoraName,removedPresets=removeAppliedOutfitsForLora(select.value);row.remove();saveLoraState();renderRegions();if(wasActive){const remaining=document.querySelector('#loras select');selectLoraNote(remaining?remaining.value:'')}else promptEditorChanged();$('status').textContent=removedPresets?'已移除 LoRA，并撤销它通过预设加入的提示词；手写内容已保留。':'已移除 LoRA。'};row.append(select,strength,remove);$('loras').appendChild(row);if(name){selectLoraNote(name);saveLoraState()}else promptEditorChanged();renderRegions();return row}
function clearLoras(){const removed=appliedOutfits.length;[...appliedOutfits].forEach(p=>removeOutfitSections(p.item,p.state));setAppliedOutfits([]);$('loras').innerHTML='';saveLoraState();selectLoraNote('');promptEditorChanged();$('status').textContent=removed?'已清空 LoRA，并撤销其预设加入的提示词；手写内容已保留。':'已清空 LoRA。'}
function find(needle,list){return listOrEmpty(list).find(x=>x.toLowerCase().includes(needle.toLowerCase()))||''}
function isAnimaSelected(){return(catalog.anima_models||[]).includes($('model').value)}
function isKrea2Selected(){return(catalog.krea2_models||[]).includes($('model').value)}
function isIllustriousSelected(){const name=String($('model').value||'').replace(/\\/g,'/').toLowerCase(),file=name.split('/').pop();return!isAnimaSelected()&&!isKrea2Selected()&&(name.includes('illustrious')||file.includes('ilxl')||/^(wai|milmu|spectacular)/.test(file))}
function promptFamilyClient(){return isAnimaSelected()?'anima':isKrea2Selected()?'krea2':isIllustriousSelected()?'illustrious':'sdxl'}
function selectedLoraPayload(){return[...$('loras').children].map(r=>({name:r.children[0].value,weight:r.children[1].value})).filter(x=>x.name)}
function collectPromptSections(){return Object.fromEntries(Object.entries(PROMPT_SECTION_IDS).map(([key,id])=>[key,$(id)?.value||'']))}
function collectPromptState(){return{sections:collectPromptSections(),negative:$('negative').value,safetyLevel:$('safetyLevel').value,promptMode:$('promptMode').value}}
function savePromptFamilyState(){if(!currentPromptFamily)return;try{sessionStorage.setItem('easyPanelPromptV2:'+currentPromptFamily,JSON.stringify(collectPromptState()))}catch{}}
function restorePromptFamilyState(family){let state=null;try{state=JSON.parse(sessionStorage.getItem('easyPanelPromptV2:'+family)||'null')}catch{}if(state?.sections){Object.entries(PROMPT_SECTION_IDS).forEach(([key,id])=>{$(id).value=state.sections[key]||''});$('negative').value=state.negative||'';$('safetyLevel').value=state.safetyLevel||'safe';$('promptMode').value=state.promptMode||'style_test'}else applyPromptPreset('style_test',true);syncMaturePrompt()}
function selectedTriggerListClient(){const found=[];selectedLoraPayload().forEach(lora=>{const note=loraNoteForName(lora.name),trigger=String(note.trigger||'').trim();if(trigger&&!found.some(item=>item.toLowerCase()===trigger.toLowerCase()))found.push(trigger)});return found}
function updatePromptProfileStrip(){const family=promptFamilyClient(),level=$('safetyLevel').value,name=String($('model').value||'').toLowerCase();let prefix=family==='anima'?(name.includes('aesthetic')?`masterpiece, best quality, ${level}`:`masterpiece, best quality, score_7, ${level}`):family==='krea2'?'（Krea 2 直接理解提示词，无质量前缀）':'masterpiece, best quality, highres';$('promptProfilePrefix').textContent='模型前缀：'+prefix;const triggers=selectedTriggerListClient();$('promptTriggerSummary').textContent=triggers.length?'自动触发词：'+triggers.join(' · '):'未选择带触发词的 LoRA'}
function promptCompilePayload(){return{model:$('model').value,loras:selectedLoraPayload(),prompt:'',negative:$('negative').value,promptSections:collectPromptSections(),promptMode:$('promptMode').value,safetyLevel:$('safetyLevel').value,mature:$('mature').checked,animaHardTags:$('animaHardTags').value,animaSoftPhrases:$('animaSoftPhrases').value,animaNLTags:$('animaNLTags').value,regionGlobalPrompt:$('regionGlobalPrompt')?.value||'',regions:$('regionsEnabled')?.checked?regions:[],colorCorrection:colorCorrectionPayload()}}
function renderPromptCompilation(data){$('compiledPositive').textContent=data.positive||'（空）';$('compiledNegative').textContent=data.negative||'（空）';const lines=[];(data.errors||[]).forEach(item=>lines.push('错误：'+item));(data.warnings||[]).forEach(item=>lines.push('提示：'+item));$('promptDiagnostics').textContent=lines.length?lines.join('\n'):'检查通过：未发现重复、结构冲突或 LoRA 底模问题。';$('promptDiagnostics').className='small '+((data.errors||[]).length?'diagnostic-error':(data.warnings||[]).length?'diagnostic-warning':'');$('promptCount').textContent=`${data.positiveTerms||0} 个最终标签 · ${data.negativeTerms||0} 个负面标签`;updatePromptProfileStrip()}
