function effectiveOutputSize(){const raw=String($('size')?.value||'832x1216').split('x').map(Number),baseWidth=raw[0]||832,baseHeight=raw[1]||1216,hires=isIllustriousSelected()&&$('illustriousMode')?.value==='hires';let scale=hires?Number($('hiresScale')?.value||1.25):1;if(!Number.isFinite(scale))scale=1.25;scale=Math.max(1,Math.min(1.5,scale));const width=Math.round(baseWidth*scale/8)*8,height=Math.round(baseHeight*scale/8)*8;return{baseWidth,baseHeight,width,height,scale,hires,baseMegapixels:baseWidth*baseHeight/1e6,megapixels:width*height/1e6}}
function updateSizeInfo(){const root=$('sizeInfo');if(!root)return;const size=effectiveOutputSize();if(isIllustriousSelected()&&$('illustriousMode')?.value==='repair'){root.className='small';root.textContent='局部修复模式：成图尺寸以原图为准，请上传原图并涂出要重绘的区域。';return size}let advice='8GB 显存建议一次生成 1 张。',warning=false;if(size.hires&&size.megapixels>1.9){advice='8GB 显存风险较高：建议改用精准模式，或将放大倍率降到 1.10–1.15×。';warning=true}else if(size.megapixels>1.5){advice='8GB 通常可尝试，但请一次生成 1 张；显存不足时改用精准模式。';warning=true}else if(size.baseMegapixels>=1.2){advice='属于合理的大图范围，8GB 建议使用精准模式并一次生成 1 张。'}if(isAnimaSelected()&&size.baseMegapixels>1.25){advice='Anima 在 8GB 上生成该尺寸压力较大；若显存不足请改用 896×1344 或 1024×1024。';warning=true}else if(isKrea2Selected()&&size.baseMegapixels>1.25){advice='Krea 2 在 8GB 上生成该尺寸压力大（会走 CPU 卸载变慢）；建议 896×1344 或 1024×1024 以内。';warning=true}root.className='small'+(warning?' diagnostic-warning':'');root.textContent=`实际成图约 ${size.width} × ${size.height}（${size.megapixels.toFixed(2)} MP）。${advice}`;return size}
function applyIllustriousMode(){const enabled=isIllustriousSelected(),mode=enabled?$('illustriousMode').value:'precision',hires=mode==='hires',repair=mode==='repair';$('hiresControls').style.display=hires?'block':'none';$('repairControls').style.display=repair?'block':'none';const output=updateSizeInfo();if(enabled){const preset=illustriousModelPreset();if(hires)$('status').textContent=`Illustrious 高清模式：${preset.sampler} / ${preset.scheduler} 二次采样，预计输出 ${output.width}×${output.height}。`;else if(repair)$('status').textContent='Illustrious 局部修复：上传原图并涂出重绘区域，仅重绘蒙版内内容（成图尺寸以原图为准）。';else $('status').textContent=`Illustrious 精准模式：单次采样，预计输出 ${output.width}×${output.height}，最适合判断画风 LoRA。`}}
