function removePromptFragment(source,fragment){const value=String(source||'').trim(),target=String(fragment||'').trim();if(!target)return value;const pattern=new RegExp(`(^|,\\s*)${escapePromptRegex(target)}(?=\\s*,|$)`);return value.replace(pattern,(_,prefix)=>prefix?', ':'').replace(/^,\s*|\s*,\s*$/g,'').replace(/,\s*,/g,', ').trim()}
