function countCategory(term){if(COUNT_TERMS.solo.includes(term))return'solo';if(COUNT_TERMS.single.includes(term))return'single';if(COUNT_TERMS.multi.includes(term))return'multi';return''}
function countTermConflicts(presetCounts,existingTerm){const cat=countCategory(existingTerm);if(!cat||presetCounts.includes(existingTerm))return false;const hasSolo=presetCounts.some(t=>countCategory(t)==='solo'),hasSingle=presetCounts.some(t=>countCategory(t)==='single'),hasMulti=presetCounts.some(t=>countCategory(t)==='multi');if(cat==='solo')return hasMulti;if(cat==='single')return hasSingle||hasMulti;if(cat==='multi')return hasSolo||hasSingle||hasMulti;return false}
function insertOutfitSections(item){const added={},removed={};OUTFIT_SECTIONS.forEach(sec=>{const text=outfitSectionValue(item,sec);if(!text)return;const field=$(sec.field);if(!field)return;let base=splitClientTerms(field.value);const incoming=splitClientTerms(text),presetCounts=incoming.map(normalizedClientTerm).filter(t=>ALL_COUNT_TERMS.includes(t));if(presetCounts.length){const dropped=base.filter(term=>countTermConflicts(presetCounts,normalizedClientTerm(term)));if(dropped.length){removed[sec.key]=dropped;base=base.filter(term=>!dropped.includes(term))}}const known=new Set(base.map(normalizedClientTerm)),missing=incoming.filter(term=>{const key=normalizedClientTerm(term);return key&&!known.has(key)});if(missing.length||(removed[sec.key]||[]).length){const baseText=base.join(', '),newCounts=missing.filter(term=>ALL_COUNT_TERMS.includes(normalizedClientTerm(term))),newOthers=missing.filter(term=>!ALL_COUNT_TERMS.includes(normalizedClientTerm(term))),parts=[];if(newCounts.length)parts.push(newCounts.join(', '));if(baseText)parts.push(baseText);if(newOthers.length)parts.push(newOthers.join(', '));field.value=parts.join(', ');if(missing.length)added[sec.key]=missing}});return{added,removed}}
function removeOutfitSections(item,state){const added=state?.added||{},removed=state?.removed||{};OUTFIT_SECTIONS.forEach(sec=>{const field=$(sec.field);if(!field)return;let value=field.value;(added[sec.key]||[]).forEach(term=>{value=removePromptFragment(value,term)});const restore=(removed[sec.key]||[]).filter(term=>{const key=normalizedClientTerm(term);return key&&!splitClientTerms(value).some(cur=>normalizedClientTerm(cur)===key)});if(restore.length){const currentTerms=splitClientTerms(value),restoreCounts=restore.filter(t=>ALL_COUNT_TERMS.includes(normalizedClientTerm(t))),restoreOthers=restore.filter(t=>!ALL_COUNT_TERMS.includes(normalizedClientTerm(t))),currentCounts=currentTerms.filter(t=>ALL_COUNT_TERMS.includes(normalizedClientTerm(t))),currentOthers=currentTerms.filter(t=>!ALL_COUNT_TERMS.includes(normalizedClientTerm(t)));value=[].concat(restoreCounts,currentCounts,currentOthers,restoreOthers).join(', ')}field.value=value})}
