function regionWarnings(){if(!$('regionsEnabled')||!$('regionsEnabled').checked||!regions.length)return[];const ws=[];const[width,height]=$('size').value.split('x').map(Number),portrait=height>width,minSide=Math.min(width,height);if(regions.length<2)ws.push('只有一个角色区域；多人分区至少应创建两个角色。');regions.forEach((r,i)=>{const label=r.name?('「'+r.name+'」'):('角色 '+(i+1)),narrow=(r.width<=.55&&r.height>=.9)&&(r.x<.15||r.x+r.width>.85);if(!String(r.prompt||'').trim())ws.push(label+'尚未填写专属提示词。');if(portrait&&narrow)ws.push('竖版下左右布局，'+label+'区域过窄；建议横版 1216×832 或改上下布局。');if(Number(r.strength)<.75)ws.push(label+'区域强度过低，容易被全局提示覆盖；建议 0.9–1.15。');if(Number(r.strength)>1.5)ws.push(label+'区域强度过高，容易出现硬边和肢体变形；建议 0.9–1.15。');for(let j=i+1;j<regions.length;j++){const b=regions[j],ow=Math.max(0,Math.min(r.x+r.width,b.x+b.width)-Math.max(r.x,b.x)),oh=Math.max(0,Math.min(r.y+r.height,b.y+b.height)-Math.max(r.y,b.y)),overlap=ow*oh,smaller=Math.min(r.width*r.height,b.width*b.height);if(smaller&&overlap/smaller>.35)ws.push(`角色 ${i+1} 与角色 ${j+1} 重叠过大；柔边只需要约 10%–20%。`)}});const bound=regions.map(r=>r.lora).filter(Boolean);if(selectedLoraPayload().length>1&&!bound.length)ws.push('当前选择了多个 LoRA，但没有绑定到角色区域；角色 LoRA 会全局叠加，仍可能融合。');if(new Set(bound).size<bound.length)ws.push('同一个角色 LoRA 被绑定到多个区域，请确认这不是误选。');if(minSide<768)ws.push('当前多人尺寸偏小，建议长边 ≥1024（如 1216×832）。');return[...new Set(ws)]}
function updateRegionWarnings(){const ws=regionWarnings();regions.forEach((r,i)=>{const w=$('regionWarn'+i);if(w){const label=r.name?('「'+r.name+'」'):('角色 '+(i+1));w.textContent=ws.filter(x=>x.includes(label)||x.includes('角色 '+(i+1))||x.includes('尺寸')||x.includes('LoRA')).join(' ')}})}
function renderRegions(){const box=$('regionsList');if(!box)return;if(!regions.length){box.innerHTML='<span class="small">未添加角色：点下方“左右双人”快速创建。</span>';return}box.innerHTML=regions.map((r,i)=>`<div style="border:1px solid var(--line);border-radius:8px;padding:6px;margin-bottom:6px"><div style="display:flex;justify-content:space-between;align-items:center"><b>角色 ${i+1}</b><button class="secondary" type="button" onclick="removeRegion(${i})">删除</button></div><input id="regionName${i}" placeholder="角色名（可选，仅备注）" value="${esc(r.name)}" oninput="regionField(${i},'name',this.value)"><div class="two"><div><div class="field-title"><span>人物类型</span></div><select onchange="regionField(${i},'subject',this.value)"><option value="1girl"${r.subject==='1girl'?' selected':''}>1girl</option><option value="1boy"${r.subject==='1boy'?' selected':''}>1boy</option><option value="person"${r.subject==='person'?' selected':''}>person</option><option value="1other"${r.subject==='1other'?' selected':''}>1other</option></select></div><div><div class="field-title"><span>绑定角色 LoRA</span></div><select onchange="regionField(${i},'lora',this.value)">${regionLoraOptions(r.lora)}</select></div></div><textarea id="regionPrompt${i}" rows="2" placeholder="只写这个角色：角色标签、发色、瞳色、服装；hug / kiss 等双方互动请写到上方全局区" oninput="regionField(${i},'prompt',this.value)">${esc(r.prompt)}</textarea><div class="two" style="margin-top:4px"><div><div class="field-title"><span>区域</span></div><select id="regionPreset${i}" onchange="regionPresetChanged(${i})"><option value="left"${r.preset==='left'?' selected':''}>左侧（柔边）</option><option value="right"${r.preset==='right'?' selected':''}>右侧（柔边）</option><option value="top"${r.preset==='top'?' selected':''}>上侧（柔边）</option><option value="bottom"${r.preset==='bottom'?' selected':''}>下侧（柔边）</option><option value="custom"${r.preset==='custom'?' selected':''}>自定义</option></select></div><div><div class="field-title"><span>强度</span></div><input id="regionStrength${i}" type="number" min="0.75" max="1.5" step="0.05" value="${r.strength}" oninput="regionField(${i},'strength',this.value)"></div></div><div class="two" style="margin-top:4px"><div><div class="field-title"><span>X（左起点）</span></div><input id="regionX${i}" type="number" min="0" max="1" step="0.01" value="${Number(r.x.toFixed(3))}" oninput="regionField(${i},'x',this.value)"></div><div><div class="field-title"><span>Y（上起点）</span></div><input id="regionY${i}" type="number" min="0" max="1" step="0.01" value="${Number(r.y.toFixed(3))}" oninput="regionField(${i},'y',this.value)"></div></div><div class="two" style="margin-top:4px"><div><div class="field-title"><span>宽</span></div><input id="regionW${i}" type="number" min="0.05" max="1" step="0.01" value="${Number(r.width.toFixed(3))}" oninput="regionField(${i},'width',this.value)"></div><div><div class="field-title"><span>高</span></div><input id="regionH${i}" type="number" min="0.05" max="1" step="0.01" value="${Number(r.height.toFixed(3))}" oninput="regionField(${i},'height',this.value)"></div></div><div id="regionWarn${i}" class="small" style="color:#ffb4b4;margin-top:2px"></div></div>`).join('');updateRegionWarnings();toggleRegions()}
function toggleRegions(){const on=$('regionsEnabled').checked,panel=$('regionsPanel'),forcedGuidanceOff=on&&$('guidanceMode')?.value!=='off';if(panel){panel.setAttribute('aria-disabled',String(!on));panel.querySelectorAll('input,textarea,select').forEach(el=>el.disabled=!on)}if($('guidanceMode')){if(on)$('guidanceMode').value='off';$('guidanceMode').disabled=on||!currentSamplingProfile().guidance_supported;guidanceChanged(true);if(forcedGuidanceOff)$('status').textContent='多人分区已自动关闭 SAG/PAG，避免 Hook 重复计算和人物特征冲突。'}updateRegionWarnings()}
