let jobQueue=[];const JOB_QUEUE_STORAGE='easyPanelJobQueueV2',MAX_LOGICAL_JOBS=50,MAX_QUEUED_IMAGES=200;
function queuedImageCount(jobs=jobQueue){return jobs.reduce((sum,job)=>sum+Math.max(1,Math.min(16,Number.parseInt(job.batchCount,10)||1)),0)}
function saveJobQueue(){try{sessionStorage.setItem(JOB_QUEUE_STORAGE,JSON.stringify(jobQueue))}catch{}}
function loadJobQueue(){try{const saved=JSON.parse(sessionStorage.getItem(JOB_QUEUE_STORAGE)||'[]');jobQueue=Array.isArray(saved)?saved.slice(0,MAX_LOGICAL_JOBS):[]}catch{jobQueue=[]}}
function jobSummary(job){const model=String(job.model||'').replace(/\\/g,'/').split('/').pop(),loras=(job.loras||[]).map(l=>String(l.name||'').replace(/\\/g,'/').split('/').pop()).join('、')||'无 LoRA',count=Math.max(1,Number.parseInt(job.batchCount,10)||1);return `${model} · ${job.width||'?'}×${job.height||'?'} · ${count} 张 · LoRA：${loras} · seed：${job.seed}`}
function renderJobQueue(){const box=$('jobQueueList'),count=$('jobQueueCount'),images=queuedImageCount();if(count)count.textContent=jobQueue.length?`${jobQueue.length}任务 / ${images}张`:'0';if(!box)return;if(!jobQueue.length){box.textContent='队列为空：设置好模型 / LoRA / 提示词 / 尺寸 / 生成数量后点“＋ 加入任务队列”。';return}box.innerHTML=`<div style="margin-bottom:4px">已暂存 ${jobQueue.length} 个逻辑任务，共 ${images} 张（发送时按顺序执行）：</div>`+jobQueue.map((job,i)=>`<div style="display:flex;justify-content:space-between;gap:6px;padding:2px 0;border-bottom:1px dashed var(--line)"><span title="${esc(jobSummary(job))}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${i+1}. ${esc(jobSummary(job))}</span><button class="secondary" type="button" style="padding:0 6px" onclick="removeJob(${i})">×</button></div>`).join('')}
function enqueueJob(){let job;try{job=payload();job.batchCount=generationCount()}catch(e){$('status').textContent='加入队列失败：'+e.message;return}if(jobQueue.length>=MAX_LOGICAL_JOBS){$('status').textContent=`加入队列失败：最多 ${MAX_LOGICAL_JOBS} 个逻辑任务。`;return}if(queuedImageCount()+job.batchCount>MAX_QUEUED_IMAGES){$('status').textContent=`加入队列失败：展开后最多 ${MAX_QUEUED_IMAGES} 张，请先发送当前队列。`;return}jobQueue.push(job);saveJobQueue();renderJobQueue();$('status').textContent=`已加入第 ${jobQueue.length} 个任务（${job.batchCount} 张）；当前共 ${queuedImageCount()} 张。`}
function removeJob(i){jobQueue.splice(i,1);saveJobQueue();renderJobQueue();$('status').textContent='已移除队列中的任务。'}
function clearJobQueue(){jobQueue=[];saveJobQueue();renderJobQueue();$('status').textContent='任务队列已清空。'}
async function sendJobQueue(){if(!jobQueue.length){$('status').textContent='任务队列为空，请先加入任务。';return}const jobs=jobQueue.map(job=>({...job})),expected=queuedImageCount(jobs),btn=$('generate');btn.disabled=true;beginGenerationProgress(expected,'队列生成进度');$('result').classList.remove('gallery');$('result').textContent=`正在提交 ${jobs.length} 个逻辑任务，共 ${expected} 张…`;try{const r=await fetch('/api/generate-batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jobs})}),d=await r.json();if(d.error)throw Error(d.error);const all=[],submitted=d.jobs||[];submitted.forEach(item=>registerGenerationPrompt(item.prompt_id));for(const item of submitted){selectGenerationPrompt(item.prompt_id);$('status').textContent=`任务 ${item.task_index+1}/${d.logical_tasks} · 第 ${item.image_index+1}/${item.image_count} 张 · 总进度 ${item.index+1}/${d.total_images}`;all.push(...await poll(item.prompt_id,60));renderGeneratedImages(all)}renderGeneratedImages(all);jobQueue=[];saveJobQueue();renderJobQueue();$('status').textContent=`任务队列完成：${d.logical_tasks} 个任务，共生成 ${all.length}/${d.total_images} 张。`;finishGenerationProgress(true,`队列完成：${d.logical_tasks} 个任务，共 ${all.length}/${d.total_images} 张。`)}catch(e){$('status').textContent='任务队列发送/等待失败：'+e.message+' 已提交到 ComfyUI 的任务仍会继续执行。';finishGenerationProgress(false,e.message)}finally{btn.disabled=false;queue()}}
async function poll(id,maxMinutes=60){selectGenerationPrompt(id);const interval=1500,attempts=Math.ceil(maxMinutes*60*1000/interval);for(let i=0;i<attempts;i++){await new Promise(r=>setTimeout(r,interval));const h=await(await fetch('/api/history?id='+encodeURIComponent(id))).json(),item=h[id];if(item?.status?.status_str==='error')throw Error('ComfyUI 执行失败：'+workflowError(item));if(item?.outputs){const images=Object.values(item.outputs).flatMap(x=>x.images||[]);if(images.length){markGenerationPromptComplete(id);return images}}}throw Error(`等待 ComfyUI 超过 ${maxMinutes} 分钟，请到输出目录检查结果。`)}

