async function pollPosePreview(id,captureJson=false){for(let attempt=0;attempt<90;attempt++){await new Promise(resolve=>setTimeout(resolve,1000));const response=await fetch('/api/history?id='+encodeURIComponent(id)),history=await response.json(),job=history[id];if(!job?.outputs)continue;const saved=Object.values(job.outputs).flatMap(output=>output.images||[])[0];if(!saved)throw Error('ComfyUI 没有返回骨架预览图。');let valid=!captureJson;if(captureJson){const extracted=job.outputs['2']?.openpose_json?.[0];if(extracted){try{const parsed=JSON.parse(extracted),people=Array.isArray(parsed)?parsed:[parsed],points=people.flatMap(p=>(p.people||[]).flatMap(q=>q.pose_keypoints_2d||[])),strong=points.filter((v,i)=>i%3===2&&Number(v)>0.3).length;if(people.length&&strong>=6){poseExtractedJson=JSON.stringify(people);setPoseEditorReady();valid=true}}catch{}}if(!valid){const source='/output?name='+encodeURIComponent(saved.filename);$('poseSkeletonPreview').innerHTML=`<div>骨架预览（关键点可信度偏低，正在尝试其他方式）</div><img alt="OpenPose 骨架" src="${source}" style="max-width:280px;max-height:280px;border-radius:8px;border:1px solid var(--line)">`;return false}}const source='/output?name='+encodeURIComponent(saved.filename);$('poseUploadInfo').textContent=captureJson?'已提取骨架；可点击“编辑已提取骨架”手动校正。':'已更新编辑后的骨架；生成时会使用该版本。';$('poseSkeletonPreview').innerHTML=`<div>骨架预览</div><img alt="OpenPose 骨架" src="${source}" style="max-width:280px;max-height:280px;border-radius:8px;border:1px solid var(--line)">`;return valid}throw Error('等待 ComfyUI 超时，请检查 ComfyUI 队列。')}
