function batchAppendToField(fieldId,text){const incoming=splitClientTerms(text),existing=splitClientTerms($(fieldId).value),known=new Set(existing.map(normalizedClientTerm)),missing=incoming.filter(t=>{const k=normalizedClientTerm(t);return k&&!known.has(k)});if(missing.length){const cur=$(fieldId).value.trim();$(fieldId).value=cur?cur+', '+missing.join(', '):missing.join(', ')}return missing.length}
async function readImageInfo(){const file=$('imgReadFile').files[0];if(!file)return;if(imageReadPreviewUrl)URL.revokeObjectURL(imageReadPreviewUrl);imageReadPreviewUrl=URL.createObjectURL(file);$('imgReadPreview').innerHTML=`<img alt="图片预览" src="${imageReadPreviewUrl}" style="max-width:160px;max-height:160px;border-radius:8px;border:1px solid var(--line)">`;$('imgReadResult').textContent='正在读取图片内嵌参数…';imageReadInfo=null;try{const form=new FormData();form.append('image',file,file.name);const r=await fetch('/api/read-image',{method:'POST',body:form});const data=await r.json();if(data.error)throw Error(data.error);imageReadInfo=data;renderImageReadResult(data)}catch(e){$('imgReadResult').textContent='读取失败：'+e.message}}
