function renderImageReadResult(data){const lines=[],src={comfyui:'ComfyUI',a1111:'WebUI (A1111)',novelai:'NovelAI'}[data.source]||data.source||'未知',fam={anima:'Anima',illustrious:'Illustrious',sdxl:'SDXL'}[data.family]||data.family||'';lines.push(`来源：${src}${fam?' · '+fam+' 模型族':''}`);if(data.model)lines.push('模型：'+data.model);if(data.sampler||data.scheduler)lines.push(`采样器：${data.sampler||'?'} / ${data.scheduler||'?'}`);if(data.steps!=null||data.cfg!=null||data.seed!=null)lines.push(`步数 ${data.steps??'?'} · CFG ${data.cfg??'?'} · Seed ${data.seed??'?'}`);if(data.width&&data.height)lines.push(`尺寸：${data.width} × ${data.height}`);if((data.loras||[]).length)lines.push('LoRA：'+(data.loras||[]).map(l=>String(l.name||'').replace(/\\/g,'/').split('/').pop()+`(${l.strength})`).join('、'));if(data.positive)lines.push('');lines.push('正向：'+(data.positive||'（空）'));lines.push('负向：'+(data.negative||'（空）'));$('imgReadResult').textContent=lines.join('\n')}
function fillPanelFromImage(){if(!imageReadInfo){$('imgReadResult').textContent='请先读取一张图片的参数。';return}const data=imageReadInfo,notes=[],base=v=>String(v||'').replace(/\\/g,'/').split('/').pop();if(data.model){const mn=base(data.model),opt=[...$('model').options].find(o=>base(o.value).toLowerCase()===mn.toLowerCase());if(opt){$('model').value=opt.value;modelChanged();notes.push('模型：'+base(opt.value))}else notes.push('未找到本地模型：'+data.model)}if((data.loras||[]).length){const loraOpts=[...document.querySelectorAll('#loras select')].flatMap(s=>[...s.options]),added=[];(data.loras||[]).forEach(l=>{const ln=base(l.name),opt=loraOpts.find(o=>base(o.value).toLowerCase()===ln.toLowerCase());if(opt){addLora(opt.value,String(l.strength??0.7));added.push(base(opt.value))}else notes.push('未找到本地 LoRA：'+l.name)});if(added.length)notes.push('LoRA：'+added.length+' 个')}if(data.steps!=null)$('steps').value=data.steps;if(data.cfg!=null)$('cfg').value=data.cfg;if(data.seed!=null)$('seed').value=data.seed;if(data.width&&data.height){const opt=[...$('size').options].find(o=>{const wh=o.value.split('x').map(Number);return wh[0]===data.width&&wh[1]===data.height});if(opt)$('size').value=opt.value;else notes.push(`尺寸 ${data.width}×${data.height} 不在预设列表`)}if(data.positive){const sections={};splitClientTerms(data.positive).forEach(term=>{const s=inferSectionForEnglish(term);(sections[s]=sections[s]||[]).push(term)});const used=[];Object.entries(sections).forEach(([s,arr])=>{if(arr.length&&batchAppendToField(PROMPT_SECTION_IDS[s]||s,arr.join(', ')))used.push(s)});if(used.length)notes.push('正向词写入：'+used.map(sectionLabel).join('、'))}if(data.negative&&batchAppendToField('negative',data.negative))notes.push('已写入负面词');updateSizeInfo();promptEditorChanged();$('imgReadResult').textContent='已填入生成面板。'+(notes.length?'\n'+notes.join('\n'):'')}
