let repairImg=null,repairMaskCv=null,repairTintCv=null,repairImageFile=null,repairUndoStack=[],repairDrawing=false,repairLast=null,repairTool='paint',repairUpload={image:'',mask:''};
function repairMaskCtx(){return repairMaskCv?repairMaskCv.getContext('2d',{willReadFrequently:true}):null}
function renderRepairView(){const cv=$('repairCanvas');if(!cv||!repairImg)return;const w=cv.width,h=cv.height;if(repairMaskCv){if(!repairTintCv)repairTintCv=document.createElement('canvas');repairTintCv.width=w;repairTintCv.height=h;const t=repairTintCv.getContext('2d',{willReadFrequently:true});t.clearRect(0,0,w,h);t.drawImage(repairMaskCv,0,0,w,h);t.globalCompositeOperation='source-in';t.fillStyle='rgba(255,60,60,0.55)';t.fillRect(0,0,w,h)}const ctx=cv.getContext('2d');ctx.clearRect(0,0,w,h);ctx.drawImage(repairImg,0,0,w,h);if(repairTintCv)ctx.drawImage(repairTintCv,0,0,w,h)}
function pushRepairUndo(){if(!repairMaskCv)return;repairUndoStack.push(repairMaskCv.getContext('2d',{willReadFrequently:true}).getImageData(0,0,repairMaskCv.width,repairMaskCv.height));if(repairUndoStack.length>12)repairUndoStack.shift()}
function undoRepair(){if(!repairMaskCv||!repairUndoStack.length)return;repairMaskCv.getContext('2d',{willReadFrequently:true}).putImageData(repairUndoStack.pop(),0,0);renderRepairView()}
function clearRepair(){if(!repairMaskCv)return;pushRepairUndo();repairMaskCtx().clearRect(0,0,repairMaskCv.width,repairMaskCv.height);renderRepairView()}
function setRepairTool(tool){repairTool=tool;$('repairToolPaint').classList.toggle('active',tool==='paint');$('repairToolErase').classList.toggle('active',tool==='erase')}
function repairPointerPos(e){const cv=$('repairCanvas'),rect=cv.getBoundingClientRect();return{x:(e.clientX-rect.left)*cv.width/rect.width,y:(e.clientY-rect.top)*cv.height/rect.height}}
function repairStroke(from,to){const ctx=repairMaskCtx();if(!ctx)return;const r=Number($('repairBrush').value||16)/2;ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=r*2;if(repairTool==='erase')ctx.globalCompositeOperation='destination-out';else ctx.globalCompositeOperation='source-over';ctx.strokeStyle='#ffffff';ctx.beginPath();ctx.moveTo(from.x,from.y);ctx.lineTo(to.x,to.y);ctx.stroke();ctx.beginPath();ctx.arc(to.x,to.y,r,0,Math.PI*2);ctx.fill();ctx.restore();renderRepairView()}
function repairPointerDown(e){if(!repairMaskCv)return;e.preventDefault();repairDrawing=true;pushRepairUndo();const p=repairPointerPos(e);repairLast=p;repairStroke(p,p);if($('repairCanvas').setPointerCapture)$('repairCanvas').setPointerCapture(e.pointerId)}
function repairPointerMove(e){if(!repairDrawing)return;e.preventDefault();const p=repairPointerPos(e);repairStroke(repairLast||p,p);repairLast=p}
function repairPointerUp(e){repairDrawing=false;repairLast=null}
async function loadInpaintImage(){const file=$('repairFile').files[0];if(!file)return;const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{repairImg=img;repairImageFile=file;const maxSide=1024,scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight)),cv=$('repairCanvas');cv.width=Math.max(1,Math.round(img.naturalWidth*scale));cv.height=Math.max(1,Math.round(img.naturalHeight*scale));repairMaskCv=document.createElement('canvas');repairMaskCv.width=cv.width;repairMaskCv.height=cv.height;repairUndoStack=[];repairTintCv=null;repairUpload={image:'',mask:''};renderRepairView();$('repairStatus').textContent=`已载入原图 ${img.naturalWidth}×${img.naturalHeight}，在图上涂出要重绘的区域，然后点击“上传蒙版”。`};img.src=url}
function repairMaskPixelCount(){if(!repairMaskCv)return 0;const d=repairMaskCv.getContext('2d',{willReadFrequently:true}).getImageData(0,0,repairMaskCv.width,repairMaskCv.height).data;let n=0;for(let i=3;i<d.length;i+=4){if(d[i]>0)n++}return n}
async function uploadRepairMask(){if(!repairMaskCv||!repairImageFile){$('repairStatus').textContent='请先载入原图并涂出蒙版。';return}const exp=document.createElement('canvas');exp.width=repairMaskCv.width;exp.height=repairMaskCv.height;const x=exp.getContext('2d');x.fillStyle='#000000';x.fillRect(0,0,exp.width,exp.height);x.drawImage(repairMaskCv,0,0);const maskBlob=await new Promise(res=>exp.toBlob(res,'image/png'));const form=new FormData();form.append('image',repairImageFile,repairImageFile.name||'inpaint.png');form.append('mask',maskBlob,'mask.png');$('repairStatus').textContent='正在上传原图与蒙版…';try{const r=await fetch('/api/upload-inpaint',{method:'POST',body:form});const data=await r.json();if(data.error)throw Error(data.error);repairUpload={image:data.image,mask:data.mask};$('repairStatus').textContent=`已上传蒙版（${repairMaskPixelCount().toLocaleString()} px 重绘区域），可直接生成。`}catch(e){$('repairStatus').textContent='上传失败：'+e.message}}
function applyInputFontSize(value){const size=Math.max(11,Math.min(24,Number(value)||15));document.documentElement.style.setProperty('--input-font-size',size+'px');const slider=$('inputFontSize');if(slider)slider.value=size;const out=$('inputFontSizeValue');if(out)out.textContent=size+'px';try{localStorage.setItem('easyPanelInputFontSize',String(size))}catch{}}
